from pathlib import Path
import json

def render(data, methods):
 validation=json.loads((Path(__file__).resolve().parents[1]/"oracle-validation-2026-10-07/results.json").read_text())
 tables=[]
 for cond,title in [('coco-coco','COCO2017 SAE'),('cc3m-coco','CC3M SAE')]:
  rows=''
  for label,method,reg in methods:
   audits=[json.loads((data/('warmstart-'+cond)/(method+'_l2_'+reg+'_'+side+'.json')).read_text()) for side in ['image','text']]
   cells=''.join(f'<td>{d["train_squared_error_sum"]/171:.5f}</td>' for d in audits)
   cells+=''.join(f'<td>{validation[cond][method+"_l2_"+reg+"_"+side]["mse"]:.5f}</td>' for side in ['image','text'])
   rows+=f'<tr><th>{label} (λ={reg})</th>{cells}</tr>'
  tables.append(f'<div><h3>{title}</h3><table><thead><tr><th>학습 목적</th><th>학습 이미지 MSE</th><th>학습 텍스트 MSE</th><th>검증 이미지 MSE</th><th>검증 텍스트 MSE</th></tr></thead><tbody>{rows}</tbody></table></div>')
 return '''<style>#oracle-error-dialog{position:fixed;inset:0;margin:auto;width:min(1080px,94vw);max-height:88vh;overflow:auto;border:1px solid #cbd0d6;border-radius:14px;padding:28px;background:white;color:#1a1d21;box-shadow:0 20px 70px #0004}#oracle-error-dialog::backdrop{background:#0008}#oracle-error-dialog h2{font-size:27px;margin:0}#oracle-error-dialog h3{font-size:20px;margin:20px 0 10px}#oracle-error-dialog p{font-size:17px;line-height:1.55;margin:13px 0}#oracle-error-dialog table{width:100%;border-collapse:collapse;font-size:16px;font-variant-numeric:tabular-nums}#oracle-error-dialog th,#oracle-error-dialog td{padding:9px;border-bottom:1px solid #ddd;text-align:right}#oracle-error-dialog th:first-child{text-align:left}#oracle-error-dialog button{font-size:17px;padding:6px 15px;cursor:pointer}</style><dialog id="oracle-error-dialog" aria-labelledby="oracle-error-heading" onkeydown="event.stopPropagation()"><header style="display:flex;align-items:center;justify-content:space-between;gap:20px"><h2 id="oracle-error-heading">개념 예측 오차</h2><button type="button" onclick="document.getElementById('oracle-error-dialog').close()">닫기</button></header><p><b>지표는 평균 제곱오차(MSE)입니다.</b> 예측값과 개념 유무의 0·1 주석 사이 차이를 제곱한 뒤, 171개 개념과 표본에 걸쳐 평균합니다. 낮을수록 주석과 가깝고, 가중치 규제 벌점은 포함하지 않습니다.</p><img src="assets/2026-10-06-mapping/oracle-error-mse.svg" alt="MSE는 표본 가중치를 반영한 171개 개념의 평균 제곱오차" style="display:block;width:57%;height:auto;max-width:576px;margin:22px auto"><p><img src="assets/2026-10-06-mapping/error-inline-n.svg" alt="n" style="display:inline-block;width:0.6635em;height:1.0944em;vertical-align:-.15em;margin:0 .08em">은 표본, <img src="assets/2026-10-06-mapping/error-inline-c.svg" alt="c" style="display:inline-block;width:0.5089em;height:1.0944em;vertical-align:-.15em;margin:0 .08em">는 개념, <img src="assets/2026-10-06-mapping/error-inline-N.svg" alt="N" style="display:inline-block;width:0.9893em;height:1.0944em;vertical-align:-.15em;margin:0 .08em">은 표본 수입니다. <img src="assets/2026-10-06-mapping/error-inline-that.svg" alt="\hat{t}" style="display:inline-block;width:0.4346em;height:1.1556em;vertical-align:-.15em;margin:0 .08em">는 예측값, <img src="assets/2026-10-06-mapping/error-inline-t.svg" alt="t" style="display:inline-block;width:0.4042em;height:1.0944em;vertical-align:-.15em;margin:0 .08em">는 개념이 있으면 <img src="assets/2026-10-06-mapping/error-inline-one.svg" alt="1" style="display:inline-block;width:0.5009em;height:1.0944em;vertical-align:-.15em;margin:0 .08em">이고 없으면 <img src="assets/2026-10-06-mapping/error-inline-zero.svg" alt="0" style="display:inline-block;width:0.5417em;height:1.0944em;vertical-align:-.15em;margin:0 .08em">인 주석입니다. <img src="assets/2026-10-06-mapping/error-inline-q.svg" alt="q" style="display:inline-block;width:0.5366em;height:1.0944em;vertical-align:-.15em;margin:0 .08em">는 표본 가중치로, 이미지에서는 해당 분할에서 연결된 캡션 수이고 텍스트에서는 <img src="assets/2026-10-06-mapping/error-inline-one.svg" alt="1" style="display:inline-block;width:0.5009em;height:1.0944em;vertical-align:-.15em;margin:0 .08em">입니다.</p><p style="padding:12px 15px;background:#f3f5f7;border-radius:7px"><b>학습 오차와 COCO val2017 검증 오차를 함께 비교합니다.</b> 검증에는 학습에 사용하지 않은 이미지 5,000장과 캡션 25,014개를 사용했습니다.</p>'''+''.join(tables)+'''<ul style="font-size:17px;line-height:1.55;margin:18px 0;padding-left:24px"><li>평균 제곱오차(MSE)로 평가한 개념 예측력은 MSE와 Binary CE로 학습한 경우가 대체로 비슷했음</li></ul><p><b>※ 주의:</b> MSE는 Ridge 학습 목적함수의 예측 오차 항과 같은 기준이며, 규제 항은 제외했습니다. 따라서 CE variants의 MSE가 높더라도 자신의 학습 목적을 덜 최적화했다고 판단할 수는 없습니다.</p></dialog>'''
